def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 500:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 1.0 - ((float(supply) - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water >= 2:
        urgency += 0.7
    elif no_water >= 1:
        urgency += 0.35

    pressure = scarcity * 0.5 + urgency + desperate_count * 0.08 + rich_count * 0.05

    if hp <= 2 or no_water >= 2:
        bid = max(62.0, high_prev + 2.0, avg_prev + 6.0)
    elif pressure >= 1.0:
        bid = max(48.0, min(high_prev + 1.5, 95.0))
    elif pressure >= 0.65:
        bid = max(34.0, min(avg_prev + 2.0, high_prev * 0.72 if high_prev > 0 else 40.0))
    else:
        if supply >= 22:
            bid = 16.0
        elif supply >= 19:
            bid = 22.0
        else:
            bid = 28.0

    if high_prev >= 130.0 and hp >= 5 and no_water == 0:
        bid = min(bid, 30.0 + scarcity * 8.0)

    safe_cap = budget
    if day <= 3:
        safe_cap = min(safe_cap, 85.0)
    elif day <= 6:
        safe_cap = min(safe_cap, 95.0)
    else:
        safe_cap = min(safe_cap, 110.0)

    if hp >= 7 and no_water == 0 and supply >= 21:
        safe_cap = min(safe_cap, 40.0)

    bid = min(bid, safe_cap)
    if bid < 0.0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Identify alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents alive, conserve
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate dominant bidding pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Also consider typical upper range
        sorted_bids = sorted(yesterday_bids)
        top_two = sorted_bids[-2:] if len(sorted_bids) >= 2 else sorted_bids
        second_highest = top_two[0] if len(top_two) == 2 else top_two[0]
    else:
        highest_prev_bid = 0.0
        second_highest = 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we're close to death, bid to secure water
    if my_hp <= 2.5 or no_water_days >= 2:
        # Bid close to the highest observed pressure
        target = max(highest_prev_bid * 1.02, DAILY_SALARY * 0.85)
    else:
        # Healthy: bid just enough to beat the dominant bids
        # If opponents were bidding very high, slightly under/around to save budget.
        if highest_prev_bid >= DAILY_SALARY * 1.4:
            target = max(second_highest + 2.0, DAILY_SALARY * 0.75)
        else:
            target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.55)

    # Convert target to a feasible bid: cannot exceed budget
    bid = min(my_budget, target)

    # If supply is low relative to our requirement, slightly increase aggressiveness
    # (index-safe usage not needed since we don't index lists)
    if supply < float(WATER_REQ) * 1.1:
        bid = min(my_budget, bid * 1.05)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
